// === Tab: sketch ===
// Code demostration for the workshop - Introduction to Creative Coding: Interactive Fireworks Party

let fireworks = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	fill(0);
	rect(0, 0, width, height);
	noStroke();
}

function draw() {
	fill(0, 100); // background with opacity
	rect(0, 0, width, height);

	if (random(1) < 0.3) { // 30% chance of adding a new firework
		// add a new firework
		fireworks.push(new Firework({}));
	}

	// show the firework
	for (let i = 0; i < fireworks.length; i++) {
		fireworks[i].show();
	}

	// remove extra firework
	for (let i = fireworks.length - 1; i >= 0; i--) {
    if (fireworks[i].done()) {
      fireworks.splice(i, 1);
    }
  }
}

// === Tab: particle ===
// Individual particle
class Particle {
	constructor(args) {
		let def = {
			pos: createVector(0, 0),
			vel: createVector(0, random(-15, -10)), // createVector(0, -10),
			acc: createVector(0, 0),
			gForce: createVector(0, 0.1), // gravitational force
			r: random(2,6),
			color: color('#00ffff'),
			endColor: color('#ffffff'),
		};
		Object.assign(def,args);
		Object.assign(this,def);
	}

	applyForce() {
		this.acc.add(this.gForce); // F = ma, here it simplies to F = a * 1
	}

	update() {
		this.vel.add(this.acc);
		this.pos.add(this.vel);
		this.acc.mult(0); // clears out the acceleration
	}

	show() {
		// displays the particle
		push();
			translate(this.pos.x, this.pos.y);
			fill(this.color);
			circle(0,0,this.r);
		pop();

	}
}

// === Tab: firework ===
// contains a particle, and the explosion of particles
class Firework {
	constructor(args) {
		var def = {
			// initialize each Firework class with a particle
			firework: new Particle({
									pos: createVector(random(width), random(height)),
								}),
			// array for storing explosion of particles
			particles: [], 
			particlesCount: 0,
			explodeStatus: false,
		};
		Object.assign(def,args);
		Object.assign(this,def);
	}

	// check if the particle exceeds the browser window
	done() { 
		return this.firework.pos.y > height || this.firework.pos.y < 0;
	}

	// check if the particle reaches the highest point
	checkExplodePoint() {
		if (this.firework.vel.y >=0) {
			this.explodeStatus = true;
			this.explode();
		}
	}

	// fireworks explosion
	explode() {
		this.particlesCount = random(60, 150);
		for( let i = 0; i < this.particlesCount; i++){
			// let hue = random(0,120);
			// let endHue = random(0,120);
			let objParticle = new Particle({
				pos: createVector(this.firework.pos.x, this.firework.pos.y),
				vel: p5.Vector.random2D(),
				r: random(this.firework.r / 2, this.firework.r),

				// color: color( (baseHue+ hue)%360,360,360),
				// endColor: color( (120+ baseHue+ endHue)%360,360,360)
			})
			this.particles.push(objParticle)
		}
	}

	show() {
		push();
			blendMode(SCREEN);
			this.firework.applyForce();
			this.firework.update();

			// show the seed particle until it reaches the highest point
			if (!this.explodeStatus) {
				this.checkExplodePoint();
				this.firework.show();
			}

			// display fireworks explosion
			for (let i = 0; i < this.particles.length; i++) {
				this.particles[i].applyForce();
				this.particles[i].update();
				this.particles[i].show();
			}
		pop();
	}
}

